using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Accounting.Abstractions;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;
namespace OAS.Application.Accounting.Customers.Commands.SetCustomerStatus;
public sealed class SetCustomerStatusCommandHandler(IRepository<Customer,Guid> customers,IPartyAccountProvisioningService accounts):IRequestHandler<SetCustomerStatusCommand>
{public async Task Handle(SetCustomerStatusCommand request,CancellationToken ct){var e=await customers.GetForUpdateAsync(request.Id,ct)??throw new NotFoundException(nameof(Customer),request.Id);try{if(!Convert.FromBase64String(request.Request.RowVersion).SequenceEqual(e.RowVersion))throw new ConcurrencyException("Customer was modified by another user.");}catch(FormatException ex){throw new ConcurrencyException("Customer row version is invalid.",ex);}e.SetActive(request.Request.IsActive);customers.Update(e);await accounts.SynchronizeAsync(e.AccountId,e.NameAr,e.NameEn,e.IsActive,ct);}}
